#include <iostream>

int main() {
    int a = 7;
    int b = 2;

    std::cout << "a + b * 3 = " << a + b * 3 << '\n';
    std::cout << "(a + b) * 3 = " << (a + b) * 3 << '\n';
    std::cout << "a / b = " << a / b << '\n';
    std::cout << "a % b = " << a % b << '\n';
    std::cout << "a / b en double = " << static_cast<double>(a) / b << '\n';
    return 0;
}

#include <iomanip>
#include <iostream>

int main() {
    // Una característica (por ejemplo, la edad) que queremos llevar a [0, 1]
    constexpr double minimo = 18.0;
    constexpr double maximo = 60.0;
    double valor = 33.0;

    double normalizado = (valor - minimo) / (maximo - minimo);

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "x = " << valor << " -> " << normalizado << '\n';
    return 0;
}

