#include <iomanip>
#include <iostream>

int main() {
    constexpr double costo_hora = 2.4;  // USD por hora de GPU
    constexpr int horas = 7;
    constexpr double descuento = 0.15;

    double bruto = horas * costo_hora;
    double ahorro = bruto * descuento;
    double total = bruto - ahorro;

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Bruto:  USD " << bruto << '\n';
    std::cout << "Ahorro: USD " << ahorro << '\n';
    std::cout << "Total:  USD " << total << '\n';
    return 0;
}

#include <iomanip>
#include <iostream>

int main() {
    int n1 = 14;
